package com.bookstore.catalog;
import jakarta.persistence.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*;
@Entity @Table(name="authors") class Author { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @NotBlank String name; String biography; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getBiography(){return biography;} public void setBiography(String v){biography=v;} }
@Entity @Table(name="publishers") class Publisher { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @NotBlank String name; String address; String website; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getWebsite(){return website;} public void setWebsite(String v){website=v;} }
interface AuthorRepository extends JpaRepository<Author,Long>{} interface PublisherRepository extends JpaRepository<Publisher,Long>{}
record CatalogRequest(@NotBlank String name,String biography,String address,String website){}
@RestController @RequestMapping("/api") class SimpleCatalogController { private final AuthorRepository authors; private final PublisherRepository publishers; SimpleCatalogController(AuthorRepository a,PublisherRepository p){authors=a;publishers=p;} @GetMapping("/authors") List<Author> authors(){return authors.findAll();} @PostMapping("/authors") Author author(@Valid @RequestBody CatalogRequest r){var a=new Author();a.setName(r.name());a.setBiography(r.biography());return authors.save(a);} @GetMapping("/publishers") List<Publisher> publishers(){return publishers.findAll();} @PostMapping("/publishers") Publisher publisher(@Valid @RequestBody CatalogRequest r){var p=new Publisher();p.setName(r.name());p.setAddress(r.address());p.setWebsite(r.website());return publishers.save(p);} }
